from __future__ import annotations
from itertools import permutations
from math import factorial
from typing import List, Sequence, Tuple

Perm = Tuple[int, ...]

def prefix_stabilizer(t: int, m: int) -> List[Perm]:
    """All permutations of {0,...,t+m-1} fixing each of the first t points."""
    return [tuple(range(t)) + tail for tail in permutations(range(t, t + m))]

def agreements(sigma: Perm, tau: Perm) -> List[int]:
    return [i for i in range(len(sigma)) if sigma[i] == tau[i]]

def is_t_intersecting(family: Sequence[Perm], t: int) -> bool:
    return all(len(agreements(s, u)) >= t for s in family for u in family)

def report(t: int, m: int) -> None:
    n = t + m
    fam = prefix_stabilizer(t, m)
    print(f"t={t}, m={m}, n={n}: |Fix_t|={len(fam)}  m!={factorial(m)}  "
          f"t-intersecting={is_t_intersecting(fam, t)}")
    assert len(fam) == factorial(m)
    assert is_t_intersecting(fam, t)

if __name__ == "__main__":
    for t, m in [(1, 2), (2, 2), (3, 0), (0, 3), (1, 3), (2, 3), (1, 4)]:
        report(t, m)
    print("All prefix-stabilizer counts verified: |Fix_t| = (n-t)!.")

from __future__ import annotations
from itertools import permutations
from math import factorial
from typing import List, Tuple

Perm = Tuple[int, ...]

def is_derangement(pi: Perm) -> bool:
    return all(pi[i] != i for i in range(len(pi)))

def derangements(n: int) -> List[Perm]:
    return [p for p in permutations(range(n)) if is_derangement(p)]

def subfactorial(n: int) -> int:
    # !n = round(n!/e), computed exactly by inclusion-exclusion
    return sum((-1)**k * factorial(n) // factorial(k) for k in range(n + 1))

if __name__ == "__main__":
    for n in range(1, 7):
        d = derangements(n)
        print(f"n={n}: #derangements={len(d)}  subfactorial(n)={subfactorial(n)}")
        assert len(d) == subfactorial(n)
    print("Derangement counts match the subfactorial for n = 1..6.")

